#!/usr/bin/env node
// Regenerates src/layoutCheckSnippet.generated.ts from src/layout-check.snippet.js.
// With --check, exits 1 instead of writing when the generated file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { transformSync } from 'esbuild';

const root = fileURLToPath(new URL('..', import.meta.url));
const sourcePath = `${root}src/layout-check.snippet.js`;
const generatedPath = `${root}src/layoutCheckSnippet.generated.ts`;

const HOLDER = 'globalThis.snippet=';
const source = readFileSync(sourcePath, 'utf-8').trim();
const { code } = transformSync(`globalThis.snippet = ${source};`, { minify: true, target: 'es2020' });
const minified = code.trim().replace(/;$/, '');
if (!minified.startsWith(HOLDER)) throw new Error(`unexpected esbuild output: ${minified.slice(0, 80)}`);

const generated = `// Generated by scripts/minify-layout-snippet.mjs from src/layout-check.snippet.js. Do not edit.
export const LAYOUT_CHECK_SNIPPET = ${JSON.stringify(minified.slice(HOLDER.length))};
`;

if (process.argv.includes('--check')) {
  const current = readFileSync(generatedPath, 'utf-8');
  if (current !== generated) {
    console.error('src/layoutCheckSnippet.generated.ts is stale: run npm run snippet:build');
    process.exit(1);
  }
} else {
  writeFileSync(generatedPath, generated);
  console.log(`${source.length} -> ${minified.length - HOLDER.length} chars`);
}
